        aggregated_counts[key] = aggregated_counts.get(key, 0) + qty
    variances: List[Tuple[str, str, int]] = []
    for location in counted_locations:
        skus_at_location: Set[str] = set()
        for (sku, loc) in system_stock.keys():
            if loc == location:
                skus_at_location.add(sku)
        for (sku, loc) in aggregated_counts.keys():
            if loc == location:
                skus_at_location.add(sku)
        for sku in skus_at_location:
