        skus_in_bin = [sku for sku, _ in bin_items]
        first_idx = min(sku_first_index[sku] for sku in skus_in_bin)
        bin_keys.append((first_idx, i))

    bin_keys.sort()
    ordered_bins = [bins[i] for _, i in bin_keys]

    parcels: List[Dict[str, int]] = []
    for bin_items in ordered_bins:
